# generated by tools/ail2py.py from text_count_batch_main.ail; edit the .ail until onelang s16
from text_count import *
from ail import flush_stdout, read_bytes
import sys

def main() -> int:
    if len(sys.argv) < 3:
        print('usage: text_count_batch utf8_input utf8_needle...', file=sys.stderr)
        return 2
    try:
        text = read_bytes(sys.argv[1]).decode()
        for index in range(2, len(sys.argv)):
            needle = read_bytes(sys.argv[index]).decode()
            print(text_count(text, needle))
            flush_stdout()
        return 0
    except UnicodeDecodeError:
        print('input and needle must be UTF-8', file=sys.stderr)
        return 4
    except OSError:
        print('text search file error', file=sys.stderr)
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
